}
internal sealed class Piece { public required string Id {get;set;} public required List<Command> Commands {get;set;} public required List<Command>? Allowance {get;set;} public required bool? AllowanceClosed {get;set;} public required Annotation Annotation {get;set;} public required List<Mark> Marks {get;set;} }
internal sealed class Annotation {public required string Name {get;set;} public required string Meaning {get;set;} public required List<Command> Commands {get;set;} public required JsonElement Svg {get;set;} }
internal sealed class Command { public required string Kind {get;set;} public required List<double[]> Points {get;set;} }
internal sealed class Mark { public required string Name {get;set;} public required string Shape {get;set;} public required double[] Matrix {get;set;} }
