internal static class Preview {
 static readonly Geometry GrainStart=Geometry.Parse("M -10,0 L 2,-4 C 0,-2 0,2 2,4 Z");
 static readonly Geometry GrainEnd=Geometry.Parse("M 10,0 L -2,-4 C 0,-2 -2,2 -2,4 Z");
