 static Point[] AnnotationPoints(Piece p){string d=p.Annotation.Svg.GetProperty("d").GetString()!;return System.Text.RegularExpressions.Regex.Matches(d,@"([ML])\s*([+-]?(?:\d+\.?\d*|\.\d+)),([+-]?(?:\d+\.?\d*|\.\d+))").Select(m=>new Point(double.Parse(m.Groups[2].Value,System.Globalization.CultureInfo.InvariantCulture),double.Parse(m.Groups[3].Value,System.Globalization.CultureInfo.InvariantCulture))).ToArray();}
