 public static object[] Trace(Experiment doc)=>doc.Pieces.Select(p=>{var pts=AnnotationPoints(p);if(pts.Length<2)throw new InvalidDataException("Missing annotation");var basis=SourceMatrix(p);double start=Angle(pts[0],pts[1]),end=Angle(pts[^2],pts[^1]);bool fold=p.Id=="breanna.front";var a=Tip(pts[0],start,fold?0:-10,basis);var b=Tip(pts[^1],end,fold?0:10,basis);return (object)new {id=p.Id,allowancePresent=p.Allowance is not null,allowanceClosed=p.AllowanceClosed,annotationStart=new[]{basis.Transform(pts[0]).X,basis.Transform(pts[0]).Y},annotationEnd=new[]{basis.Transform(pts[^1]).X,basis.Transform(pts[^1]).Y},startTip=new[]{a.X,a.Y},endTip=new[]{b.X,b.Y},markerStart=p.Annotation.Svg.GetProperty("markerStart").GetString(),markerEnd=p.Annotation.Svg.GetProperty("markerEnd").GetString()};}).ToArray();
 static IEnumerable<double[]> GlyphCorners(Mark m){foreach(double x in new[]{-2.8,2.8})foreach(double y in new[]{-2.8,2.8}){var a=m.Matrix;double u=a[0]*x+a[2]*y+a[4],v=a[1]*x+a[3]*y+a[5];if(!double.IsFinite(u)||!double.IsFinite(v)||Math.Abs(u)>1e8||Math.Abs(v)>1e8)throw new InvalidDataException("Glyph bounds");yield return [u,v];}}
