 static void DrawArrow(DrawingContext dc,Point pos,double angle,Geometry shape){dc.PushTransform(new TranslateTransform(pos.X,pos.Y));dc.PushTransform(new RotateTransform(angle));dc.DrawGeometry(Brushes.Teal,null,shape);dc.Pop();dc.Pop();}
 static void DrawAnnotation(DrawingContext dc,Piece p){var points=AnnotationPoints(p);var start=Angle(points[0],points[1]);var end=Angle(points[^2],points[^1]);var figure=new PathFigure{StartPoint=points[0],IsClosed=false,IsFilled=false};foreach(var pt in points.Skip(1))figure.Segments.Add(new LineSegment(pt,true));var geo=new PathGeometry();geo.Figures.Add(figure);dc.PushTransform(new MatrixTransform(SourceMatrix(p)));dc.DrawGeometry(null,new Pen(Brushes.Teal,1),geo);bool fold=p.Id=="breanna.front";DrawArrow(dc,points[0],start,fold?FoldStart:GrainStart);DrawArrow(dc,points[^1],end,fold?FoldEnd:GrainEnd);dc.Pop();}
 public static DrawingVisual Build(Experiment doc){Codec.Validate(doc);const double width=1100,height=760,pad=35,header=100;var pts=doc.Pieces.SelectMany(p=>p.Commands.Concat(p.Allowance??[]).Concat(p.Annotation.Commands)).SelectMany(c=>c.Points).Concat(doc.Pieces.SelectMany(p=>p.Marks).SelectMany(GlyphCorners)).Concat(doc.Pieces.SelectMany(ArrowBounds)).ToArray();double minX=pts.Min(q=>q[0]),maxX=pts.Max(q=>q[0]),minY=pts.Min(q=>q[1]),maxY=pts.Max(q=>q[1]);if(maxX<=minX||maxY<=minY)throw new InvalidDataException("Bounds");double scale=Math.Min((width-2*pad)/(maxX-minX),(height-header-2*pad)/(maxY-minY));var visual=new DrawingVisual();using var dc=visual.RenderOpen();dc.DrawRectangle(Brushes.White,null,new Rect(0,0,width,height));var typeface=new Typeface("Segoe UI");var culture=System.Globalization.CultureInfo.GetCultureInfo("tr-TR");dc.DrawText(new FormattedText("SENTETİK · TOPOLOJİ VE LİSANS DOĞRULANMADI · ÜRETİM İÇİN DEĞİLDİR",culture,FlowDirection.LeftToRight,typeface,15,Brushes.DarkRed,1),new Point(20,10));dc.DrawText(new FormattedText("Mor: dikiş · Turuncu: pay · Mavi: iplik/kumaş katı · Çentik · Kaynak metni gösterilmez",culture,FlowDirection.LeftToRight,typeface,13,Brushes.Black,1),new Point(20,34));var allowanceStatus=string.Join(" · ",doc.Pieces.Select(p=>($"{p.Id}: pay "+(p.Allowance is null?"yok":p.AllowanceClosed==true?"kapalı":"açık"))));dc.DrawText(new FormattedText(allowanceStatus,culture,FlowDirection.LeftToRight,typeface,12,Brushes.DarkOrange,1),new Point(20,52));dc.PushTransform(new MatrixTransform(scale,0,0,scale,pad-minX*scale,header+pad-minY*scale));var seamPen=new Pen(Brushes.DarkSlateBlue,1.4/scale);var saPen=new Pen(Brushes.DarkOrange,1.2/scale){DashStyle=DashStyles.Dash};var markPen=new Pen(Brushes.DarkMagenta,.7/scale);foreach(var p in doc.Pieces){dc.DrawGeometry(null,seamPen,GeometryFor(p.Commands,true));if(p.Allowance is not null)dc.DrawGeometry(null,saPen,GeometryFor(p.Allowance,p.AllowanceClosed==true));DrawAnnotation(dc,p);foreach(var m in p.Marks){var a=m.Matrix;dc.PushTransform(new MatrixTransform(a[0],a[1],a[2],a[3],a[4],a[5]));dc.DrawEllipse(null,markPen,new Point(0,0),2.8,2.8);if(m.Shape=="notch")dc.DrawEllipse(Brushes.DarkMagenta,null,new Point(0,0),1.4,1.4);else{dc.DrawLine(markPen,new Point(-1.1,-1.1),new Point(1.1,1.1));dc.DrawLine(markPen,new Point(1.1,-1.1),new Point(-1.1,1.1));}dc.Pop();}}dc.Pop();return visual;}
 public static byte[] Render(Experiment doc){var bmp=new RenderTargetBitmap(1100,760,96,96,PixelFormats.Pbgra32);bmp.Render(Build(doc));var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bmp));using var stream=new MemoryStream();enc.Save(stream);return stream.ToArray();}
}

internal static class Program {
 [STAThread] static int Main(string[] args){try{if(args.Length>1||(args.Length==1&&args[0]!="--validate-only"))throw new InvalidDataException("Unknown mode");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(3));using var buffer=new MemoryStream();var input=Console.OpenStandardInput();var chunk=new byte[8192];while(true){int n=Task.Run(()=>input.Read(chunk,0,chunk.Length)).WaitAsync(timeout.Token).GetAwaiter().GetResult();if(n==0)break;if(buffer.Length+n>1_000_000)throw new InvalidDataException("Input too large");buffer.Write(chunk,0,n);}var inputBytes=buffer.ToArray();var doc=Codec.Read(inputBytes);if(args.Length==1){Console.Write("VALID");return 0;}var encoded=Codec.Write(doc);var roundtrip=Codec.Read(encoded);if(!encoded.SequenceEqual(Codec.Write(roundtrip)))throw new InvalidDataException("Roundtrip");var root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../runtime"));Directory.CreateDirectory(root);string id=Guid.NewGuid().ToString("N"),v1=Path.Combine(root,id+"-experiment.json"),legacy=Path.Combine(root,id+"-legacy.json"),legacyV1=Path.Combine(root,id+"-legacy-v1.json"),image=Path.Combine(root,id+"-preview.png");bool madeV1=false,madeLegacy=false,madeLegacyV1=false,madeImage=false,completedImage=false;try{using(var file=new FileStream(v1,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeV1=true;file.Write(encoded);}if(!Codec.Write(Codec.Read(File.ReadAllBytes(v1))).SequenceEqual(encoded))throw new InvalidDataException("File roundtrip");var old=new ProjectDocument{Name="Synthetic legacy",Pieces=[new PatternPiece{Name="Synthetic triangle",Points=[new(0,0),new(10,0),new(0,10)],Closed=true}]};using(var reserved=new FileStream(legacy,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeLegacy=true;}ProjectStorage.Save(old,legacy);var loaded=ProjectStorage.Load(legacy);if(loaded.Pieces.Count!=1||!loaded.Pieces[0].Points.SequenceEqual(old.Pieces[0].Points)||!loaded.Pieces[0].Closed)throw new InvalidDataException("Legacy read");var legacyText=File.ReadAllText(legacy);using(var f=new FileStream(legacyV1,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeLegacyV1=true;using var w=new StreamWriter(f,new UTF8Encoding(false));w.Write("[1,"+legacyText+"]");}var loadedV1=ProjectStorage.Load(legacyV1);if(!loadedV1.Pieces[0].Points.SequenceEqual(old.Pieces[0].Points))throw new InvalidDataException("Legacy v1 read");var repo=new DirectoryInfo(AppContext.BaseDirectory);while(repo is not null&&!File.Exists(Path.Combine(repo.FullName,"AGENTS.md")))repo=repo.Parent;if(repo is null)throw new InvalidDataException("Fixture root");var existing=Path.Combine(repo.FullName,"tests","TekstilCAD.Tests","Fixtures","studio-0.3-native.tcad");var existingBefore=File.ReadAllBytes(existing);var existingHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(existingBefore));if(existingHash!="1F11E3C99FBE6222A2EB71353E62AA64FFF4B722DEDAB8C3957627E66EB7A5C3")throw new InvalidDataException("Fixture changed");var published=ProjectStorage.Load(existing);if(published.Pieces.Count!=2||!published.Pieces[0].Closed||published.Pieces[1].Closed||published.Pieces[0].Points[0].X!=0.123456789||!existingBefore.SequenceEqual(File.ReadAllBytes(existing)))throw new InvalidDataException("Historical fixture");bool legacyRejected=false;try{ProjectStorage.Load(v1);}catch(InvalidDataException){legacyRejected=true;}if(!legacyRejected)throw new InvalidDataException("Production reader accepted experiment");Preview.VerifyGeometry(roundtrip);var png=Preview.Render(roundtrip);if(png.Length<2000)throw new InvalidDataException("Preview empty");using(var f=new FileStream(image,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeImage=true;f.Write(png);}completedImage=true;Console.Write(JsonSerializer.Serialize(new {status="PASS",preview=image,legacyRead=true,legacyV1Read=true,existingLegacyFixtureRead=true,productionReaderRejected=true,pieces=roundtrip.Pieces.Count,curves=roundtrip.Pieces.Sum(p=>p.Commands.Count(c=>c.Kind=="curve")),marks=roundtrip.Pieces.Sum(p=>p.Marks.Count),productionApproved=false,renderTrace=Preview.Trace(roundtrip),document=JsonSerializer.Deserialize<JsonElement>(encoded)}));}finally{if(madeV1&&File.Exists(v1))File.Delete(v1);if(madeLegacy&&File.Exists(legacy))File.Delete(legacy);if(madeLegacyV1&&File.Exists(legacyV1))File.Delete(legacyV1);if(madeImage&&!completedImage&&File.Exists(image))File.Delete(image);}}catch{Console.Error.Write("INVALID_SYNTHETIC_DOCUMENT");return 1;}return 0;}
}
